#include <stdio.h>

// Define the structure of the linked list node
struct Node {
    int value;
    struct Node *next;
};

// Function to reverse the linked list in-place
struct Node *reverse(struct Node *head) {
    if (head == NULL || head->next == NULL) {
        return head; // No reversal needed for a single or empty list
    }

    struct Node *prev = NULL;
    struct Node *current = head;
    struct Node *next;

    while (current != NULL) {
        next = current->next; // Save the next node
        current->next = prev; // Reverse the current node's pointer
        prev = current; // Move prev to current
        current = next; // Move current to the next node
    }

    return prev; // The new head of the reversed list
}

// Function to print the linked list
void printList(struct Node *head) {
    while (head != NULL) {
        printf("%d -> ", head->value);
        head = head->next;
    }
    printf("NULL\n");
}

int main() {
    // Create a sample linked list
    struct Node *head = (struct Node *)malloc(sizeof(struct Node));
    head->value = 1;
    head->next = (struct Node *)malloc(sizeof(struct Node));
    head->next->value = 2;
    head->next->next = (struct Node *)malloc(sizeof(struct Node));
    head->next->next->value = 3;
    head->next->next->next = NULL;

    printf("Original list: ");
    printList(head);

    // Reverse the list
    head = reverse(head);

    printf("Reversed list: ");
    printList(head);

    // Free the allocated memory
    while (head != NULL) {
        struct Node *temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
```

This code snippet defines a function `reverse` that reverses a singly linked list in-place using O(1) extra space. It also includes a `printList` function to display the linked list and a `main` function to demonstrate the usage of the `reverse` function. The `main` function also includes memory allocation and deallocation to ensure proper memory management.
